-- A pool membership may carry a from-date and a to-date (both included; null: no bound). A member whose dates do not
-- include the sheet's today is left out of the pool: not in its total share, not in its balance, no cut.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
ALTER TABLE pool_member ADD CONSTRAINT pool_member_dates
    CHECK (from_date IS NULL OR to_date IS NULL OR to_date >= from_date);
-- A person's holds are dated: each row is a hold from its from-date to its to-date (null: with no end), and a person
-- may have several over time. Only their open claims dated within a hold, not bound by a statement, are left out of
-- the live totals. A person held before keeps a hold from the beginning of time.
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE   NOT NULL,
    to_date   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- Whether a person is on hold. While held, their open claims count in no live total; their settled ones still do.
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Embeddable;
import java.time.LocalDate;

/** A hold on a person from its from-date to its to-date, both included (a null to-date: with no end). */
@Embeddable
public class DatedHold {

    @Column(name = "from_date", nullable = false)
    private LocalDate from;

    @Column(name = "to_date")
    private LocalDate to;

    /** The sheet's today when the hold was put; null: before that was kept. */
    @Column(name = "made_on")
    private LocalDate madeOn;

    protected DatedHold() {
    }

    public DatedHold(LocalDate from, LocalDate to) {
        this(from, to, null);
    }

    public DatedHold(LocalDate from, LocalDate to, LocalDate madeOn) {
        this.from = from;
        this.to = to;
        this.madeOn = madeOn;
    }

    /** Whether the hold was put while the sheet's today was on or before the day. */
    public boolean madeBy(LocalDate day) {
        return madeOn == null || !madeOn.isAfter(day);
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    /** Whether the date falls within the hold. */
    public boolean covers(LocalDate date) {
        return date != null && !date.isBefore(from) && (to == null || !date.isAfter(to));
    }
}

